350	    @Transactional
351	    public void matchOrderBid(Xzj27 orderBid) {
352	        try {
353	            if (orderBid == null) {
354	                throw new Xvt58Exception("주문 입찰 정보가 없습니다.");
355	            }
356	
357	            if (orderBid.getStatus() == Xtz73Status.MATCHED) {
358	                throw new Xmd85Exception("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
359	            }
360	
361	            orderBid.updateStatus(Xtz73Status.MATCHED);
362	        } catch (Exception e) {
363	            if (e instanceof Xdg64Exception) {
364	                throw e;
365	            }
366	            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
367	            throw new Xhz43Exception("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
368	        }
369	    }
