117	    private void validatePaymentRequest(Xdg64 order, Xrd81 user, Xbf54RequestDto requestDto) {
118	        if (order == null) {
119	            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
120	        }
121	
122	        if (user == null) {
123	            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
124	        }
125	
126	        if (requestDto == null) {
127	            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
128	        }
129	
130	
131	        if (!order.getId().equals(requestDto.getOrderId())) {
132	            throw new Xbf54Exception(Xbf54ErrorCode.PAYMENT_VALIDATION_FAILED,
133	                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
134	        }
135	
